//! Extra device containers for robots 2..N in the docker simulation of
//! `profinet-headplc-robot-simulation/docker` (robot 1 reuses the existing `device` service).

use std::fmt::Write as _;

use crate::config::Config;
use crate::ir::CellPlan;

pub fn render(plan: &CellPlan, cfg: &Config) -> (String, String) {
    let n = &cfg.network;
    let mut c = String::new();
    let _ = writeln!(
        c,
        "# generated by {} for {} - use from profinet-headplc-robot-simulation/docker:",
        crate::backend::codesys::GENERATOR,
        plan.cell_id
    );
    for r in plan.robots.iter().skip(1).filter(|r| !r.addr.external) {
        let _ = writeln!(
            c,
            "#   cp -r device-config device-{}-config",
            r.addr.tag.to_lowercase()
        );
    }
    c.push_str("#   docker compose -f docker-compose.yml -f <out>/docker/docker-compose.robots.yml up -d --build\n");
    if let Some(r) = plan.robots.first() {
        let _ = writeln!(
            c,
            "# {} {} {} {} -> existing service 'device'{}",
            r.addr.tag,
            r.ns,
            r.addr.station,
            r.addr.ip,
            if r.addr.external {
                " (external: not started)"
            } else {
                ""
            }
        );
    }
    // External robots (a KUKA VC, a real controller) answer as the PROFINET device themselves:
    // no service of their own, and robot 1's base service 'device' is not started. setup.sh reads
    // this line (stops those containers, leaves them out of `compose up`).
    let external: Vec<String> = plan
        .robots
        .iter()
        .enumerate()
        .filter(|(_, r)| r.addr.external)
        .map(|(i, r)| service_name(i, &r.addr.tag))
        .collect();
    if !external.is_empty() {
        let _ = writeln!(c, "# plan2cell-external-services: {}", external.join(" "));
    }
    let sims: Vec<_> = plan
        .robots
        .iter()
        .skip(1)
        .filter(|r| !r.addr.external)
        .collect();
    if sims.is_empty() {
        c.push_str("services: {}\n");
    } else {
        c.push_str("services:\n");
        for r in sims {
            let t = r.addr.tag.to_lowercase();
            let _ = writeln!(
                c,
                "  device-{t}:                       # {} {} {}\n    build:\n      context: .\n      args:\n        LIB_DIR: ${{LIB_DIR:-x86_64-linux-gnu}}\n        RUNTIME_VERSION: ${{RUNTIME_VERSION:-unknown}}\n    container_name: codesys-device-{t}\n    cap_add: [NET_ADMIN, NET_RAW]\n    sysctls:\n      - net.ipv4.ip_forward=1\n    networks:\n      {}:\n        ipv4_address: {}\n      codemeter_net:\n    restart: unless-stopped\n    volumes:\n      - ./device-{t}-config:/etc/codesyscontrol\n      - ./device-{t}-data:/var/opt/codesys\n      - /var/run:/var/run",
                r.addr.tag, r.ns, r.addr.station, n.docker_network, r.addr.ip
            );
        }
    }
    let mut md = String::new();
    let _ = writeln!(md, "# Docker simulation for {}\n", plan.cell_id);
    md.push_str("| Robot | Station | IP | Service | Gateway port |\n|---|---|---|---|---|\n");
    for (i, r) in plan.robots.iter().enumerate() {
        let svc = if r.addr.external {
            "external (not simulated)".to_string()
        } else {
            service_name(i, &r.addr.tag)
        };
        let _ = writeln!(
            md,
            "| {} {} | {} | {} | {} | {} |",
            r.addr.tag, r.ns, r.addr.station, r.addr.ip, svc, n.device_gateway_port
        );
    }
    let _ = writeln!(
        md,
        "\nHead PLC: `codesys-master` at {} (gateway port {}).\n\n1. In `profinet-headplc-robot-simulation/docker`, copy `device-config` once per extra robot (see the comments in `docker-compose.robots.yml`).\n2. `docker compose -f docker-compose.yml -f <out>/docker/docker-compose.robots.yml up -d --build`, then rerun the bridge settings from `install.sh` (multicast snooping off, promiscuous veths).\n3. Download each `RobotSim_*` project to its container (by IP) before the head PLC project.\n\nEach runtime hosts exactly one PROFINET device with a unique station name. Every container needs its own CODESYS runtime licence (or demo mode, which stops after a while).",
        n.head_ip, n.head_gateway_port
    );
    (c, md)
}

/// Compose service of robot `i` (0-based): robot 1 is the base file's `device`.
fn service_name(i: usize, tag: &str) -> String {
    if i == 0 {
        "device".to_string()
    } else {
        format!("device-{}", tag.to_lowercase())
    }
}
